#!/usr/bin/env python3
"""
KPR Preferred Equity + Lender Rollup — one-click deploy
Upload to Replit project root, then paste into the Agent box:
  Read deploy_debt_lender.py and run it in the shell.
"""
import os, base64

BASE = os.path.dirname(os.path.abspath(__file__))

def patch(path, old, new, label):
    full = os.path.join(BASE, path)
    try:
        with open(full, encoding="utf-8") as f: content = f.read()
    except FileNotFoundError:
        print(f"  MISS {label} — {path} not found"); return
    if old not in content:
        print(f"  SKIP {label} — already applied"); return
    with open(full, "w", encoding="utf-8") as f: f.write(content.replace(old, new, 1))
    print(f"  OK   {label}")

def write_new(path, b64, label):
    full = os.path.join(BASE, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "wb") as f: f.write(base64.b64decode(b64))
    print(f"  OK   {label}")

print("\n=== KPR Preferred Equity + Lender Rollup ===\n")

